                cpu_percent = float(output.strip().split('%')[0])
        except:
            cpu_percent = 0.0

        records.append({
            "timestamp": time.time(),
            "cpu_percent": cpu_percent
        })
        next_time += interval

    try:
        with open(LOGFILE_PATH, 'w') as f:
            json.dump(records, f)
    except IOError:
        return None

    return LOGFILE_PATH

